const CACHE='prognos-v6';self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['./','index.html','style.css?rev=6','comfort.css?rev=6','comfort.js?rev=6','search.js?rev=6','consultant.js?rev=6','consultant.css?rev=6','app.js?rev=6','data.js','manifest.json','directory-index.js','directory.js?rev=6','directory-details.json','library-provenance.json'])));self.skipWaiting()});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('prognos-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request).then(r=>r||new Response('Offline: this resource has not been saved.',{status:503}))))});
